package de.labrwn.completiontracker.catalog;

import com.google.gson.Gson;
import de.labrwn.completiontracker.CompletionTracker;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

/**
 * The list of everything that can be completed: survival items, mobs with their variants, and
 * advancement difficulties. Generated by tools/gen_catalog.py into assets/completiontracker/catalog.json.
 */
public final class Catalog {
	public static class ItemDef {
		public String id;
		public String cat;
		public int diff;
		public String hint;
	}

	public static class MobDef {
		public String id;
		public String cat;
		public int diff;
		public String hint;
		public List<String> variants;
	}

	public String version;
	public List<ItemDef> items;
	public List<MobDef> mobs;
	public Map<String, Integer> advancementDifficulty;

	private static Catalog instance;

	public static synchronized Catalog get() {
		if (instance == null) {
			try (InputStream in = Catalog.class.getResourceAsStream("/assets/completiontracker/catalog.json")) {
				instance = new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Catalog.class);
			} catch (Exception e) {
				CompletionTracker.LOGGER.error("Could not load the catalog", e);
				instance = new Catalog();
				instance.items = List.of();
				instance.mobs = List.of();
				instance.advancementDifficulty = Map.of();
			}
		}
		return instance;
	}
}
